import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canPostEntry } from '../src/access.mjs';

test('an explicit posting grant permits posting', () => {
  assert.equal(canPostEntry([{ id: 'writer', grants: ['ledger:post'] }], 'writer'), true);
});

test('a different grant does not permit posting', () => {
  assert.equal(canPostEntry([{ id: 'reader', grants: ['ledger:read'] }], 'reader'), false);
});

test('missing grants do not permit posting', () => {
  assert.equal(canPostEntry([{ id: 'reader' }], 'reader'), false);
});

test('an unknown account does not inherit another account grant', () => {
  assert.equal(canPostEntry([{ id: 'writer', grants: ['ledger:post'] }], 'unknown'), false);
});

test('an empty account set denies posting', () => {
  assert.equal(canPostEntry([], 'unknown'), false);
});
